import { useTranslation } from '@fanfanlo';
import { Button } from '@mui/material';
import { useState } from 'react';
import { ScriptExamplePopup } from './ScriptExamplePopup';
import type { IScript } from '../scripts/IScript';

// 日志前缀
const LOG_PREFIX = '[ScriptExampleSelectorButton]';

export interface ScriptExamplesMap {
  beginner: IScript[];
  intermediate: IScript[];
  advanced: IScript[];
}

interface ScriptExampleSelectorButtonProps {
  examplesMap: ScriptExamplesMap | null;
  onSelectScript: (script: IScript) => void;
}

/**
 * 脚本示例选择按钮组件
 * 点击按钮弹出示例选择弹窗
 */
export function ScriptExampleSelectorButton({
  examplesMap,
  onSelectScript
}: ScriptExampleSelectorButtonProps) {
  console.log(`${LOG_PREFIX} 组件初始化`);

  const { t } = useTranslation('homepage/components/script-editor/content/v2/content');
  const [open, setOpen] = useState(false);

  const handleOpen = () => {
    console.log(`${LOG_PREFIX} 按钮被点击, 准备打开弹窗`);
    setOpen(true);
    console.log(`${LOG_PREFIX} 弹窗状态已设置为 true`);
  };

  const handleClose = () => {
    console.log(`${LOG_PREFIX} 准备关闭弹窗`);
    setOpen(false);
    console.log(`${LOG_PREFIX} 弹窗状态已设置为 false`);
  };

  const handleSelect = (script: IScript) => {
    console.log(`${LOG_PREFIX} 选中脚本: ${script.name}`);
    onSelectScript(script);
    handleClose();
  };

  const isDisabled = !examplesMap;
  console.log(`${LOG_PREFIX} 按钮是否禁用: ${isDisabled}`);

  return (
    <>
      <Button variant="contained" onClick={handleOpen} disabled={isDisabled}>
        {t('ScriptExampleSelectorButton.selectExample')}
      </Button>
      <ScriptExamplePopup
        open={open}
        onClose={handleClose}
        examplesMap={examplesMap}
        onSelectScript={handleSelect}
      />
    </>
  );
}
