import { autoWebViewJs } from '@droid/android';
import { fanfanloI18n, toProxy, useTranslation } from '@fanfanlo';
import { Alert, Box, CircularProgress, Stack, Typography } from '@mui/material';
import { ScriptEditorContextProvider } from '@src/components/script-editor/data/context';
import { loadScrptEditorData, type IScriptEditorContentData } from '@src/components/script-editor/data/script-editor.data.intf';
import type { DifficultyLevel } from '@src/services/droid-docs-api';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useDroidDocsScripts } from '../useDroidDocsScripts';
import type { IScript } from '../scripts/IScript';
import { ScriptControlBar } from './ScriptControlBar';
import { ScriptEditor } from './ScriptEditor';
import { ScriptExampleSelectorButton } from './ScriptExampleSelectorButton';
import { ScriptPermissionsEditor } from './ScriptPermissionsEditor';

// 日志前缀
const LOG_PREFIX = '[ScriptEditorContentV2]';

export function ScriptEditorContentV2({
  ns,
  initialCategory,
  initialName,
  initialScript
}: {
  ns?: string;
  initialCategory?: DifficultyLevel;
  initialName?: string;
  initialScript?: boolean;
}) {
  console.log(`${LOG_PREFIX} 组件初始化, ns: ${ns}, initialCategory: ${initialCategory}, initialName: ${initialName}, initialScript: ${initialScript}`);

  const lang = fanfanloI18n.language || 'en';
  console.log(`${LOG_PREFIX} 当前语言: ${lang}`);

  const { t } = useTranslation('homepage/components/script-editor/content/v2/content');

  // Context 数据状态
  const [contextData, setContextData] = useState<IScriptEditorContentData | null>(null);
  const [isLoadingContext, setIsLoadingContext] = useState(true);
  const [contextError, setContextError] = useState<Error | null>(null);
  console.log(`${LOG_PREFIX} contextData 是否存在: ${!!contextData}, isLoadingContext: ${isLoadingContext}`);

  // 使用 droid-docs API 获取脚本数据
  const {
    examplesMap,
    isLoadingMap,
    mapError,
    scriptError,
  } = useDroidDocsScripts(lang);

  console.log(`${LOG_PREFIX} examplesMap 是否加载: ${!!examplesMap}, isLoadingMap: ${isLoadingMap}`);

  // 使用 toProxy 管理 IScript 状态
  const [scriptData, setScriptData] = useState<IScript | null>(null);
  console.log(`${LOG_PREFIX} scriptData 是否存在: ${!!scriptData}`);

  // 运行脚本状态
  const [runScript, setRunScript] = useState('');
  console.log(`${LOG_PREFIX} runScript 状态: ${runScript ? '有内容' : '空'}`);

  // 使用 useRef 标记是否已加载 context 数据
  const hasLoadedContextRef = useRef(false);

  // 加载 context 数据
  useEffect(() => {
    console.log(`${LOG_PREFIX} context 加载 useEffect 触发, hasLoaded: ${hasLoadedContextRef.current}`);

    if (hasLoadedContextRef.current) {
      console.log(`${LOG_PREFIX} context 已加载过, 跳过`);
      return;
    }

    let mounted = true;
    console.log(`${LOG_PREFIX} 开始加载 context 数据`);

    async function loadContext() {
      try {
        setIsLoadingContext(true);
        console.log(`${LOG_PREFIX} 调用 loadScrptEditorData, ns: ${ns}`);
        const data = await loadScrptEditorData(ns);
        console.log(`${LOG_PREFIX} loadScrptEditorData 完成`, data);

        if (mounted) {
          console.log(`${LOG_PREFIX} 组件仍然挂载, 设置 context 数据`);
          setContextData(data);
          setIsLoadingContext(false);
          hasLoadedContextRef.current = true;
        } else {
          console.log(`${LOG_PREFIX} 组件已卸载, 忽略数据`);
        }
      } catch (err) {
        console.error(`${LOG_PREFIX} 加载 context 数据失败`, err);
        if (mounted) {
          setContextError(err as Error);
          setIsLoadingContext(false);
        }
      }
    }

    loadContext();

    return () => {
      console.log(`${LOG_PREFIX} context 加载 useEffect 清理`);
      mounted = false;
    };
  }, [ns]);

  // 创建空的 IScript 对象
  const createEmptyScript = (): IScript => {
    console.log(`${LOG_PREFIX} 创建空的 IScript 对象`);
    const emptyScript: IScript = {
      name: '',
      script: '',
      desc: '',
      path: '',
      version: 1,
      permissions: [],
    };
    console.log(`${LOG_PREFIX} 空 IScript 对象创建完成`);
    return toProxy(emptyScript);
  };

  // 根据 initialCategory 和 initialName 查找并加载脚本
  useEffect(() => {
    console.log(`${LOG_PREFIX} useEffect 触发, initialCategory: ${initialCategory}, initialName: ${initialName}, examplesMap 是否存在: ${!!examplesMap}`);

    // 如果没有初始化参数,创建空的 IScript
    if (!initialCategory || !initialName) {
      console.log(`${LOG_PREFIX} 没有初始化参数, 创建空的 IScript`);

      if (!scriptData) {
        console.log(`${LOG_PREFIX} scriptData 为空, 执行创建`);
        const empty = createEmptyScript();
        setScriptData(empty);
        console.log(`${LOG_PREFIX} 空 IScript 已设置`);
      } else {
        console.log(`${LOG_PREFIX} scriptData 已存在, 跳过创建`);
      }

      return;
    }

    // 如果还在加载 examplesMap,等待
    if (!examplesMap) {
      console.log(`${LOG_PREFIX} examplesMap 尚未加载, 等待`);
      return;
    }

    console.log(`${LOG_PREFIX} 开始根据 category 和 name 查找脚本`);

    // 从 examplesMap 中查找对应级别的脚本列表
    const levelScripts = examplesMap[initialCategory];
    console.log(`${LOG_PREFIX} ${initialCategory} 级别脚本列表长度: ${levelScripts?.length || 0}`);

    if (!levelScripts) {
      console.error(`${LOG_PREFIX} 找不到 ${initialCategory} 级别的脚本列表`);
      return;
    }

    // 在脚本列表中查找目标脚本
    const targetScript = levelScripts.find(s => s.path === `${initialCategory}/${initialName}`);
    console.log(`${LOG_PREFIX} 查找结果: ${targetScript ? '找到' : '未找到'}`);

    if (!targetScript) {
      console.error(`${LOG_PREFIX} 找不到脚本: ${initialCategory}/${initialName}`);
      return;
    }

    console.log(`${LOG_PREFIX} 找到脚本: ${targetScript.name}, 权限数量: ${targetScript.permissions?.length || 0}`);

    // 创建脚本的副本并使用 toProxy 包装
    const scriptCopy: IScript = {
      ...targetScript,
      permissions: targetScript.permissions ? [...targetScript.permissions] : [],
    };
    console.log(`${LOG_PREFIX} 脚本副本创建完成, permissions 数量: ${scriptCopy.permissions?.length || 0}`);

    const proxiedScript = toProxy(scriptCopy);
    console.log(`${LOG_PREFIX} 脚本已使用 toProxy 包装`);

    setScriptData(proxiedScript);
    console.log(`${LOG_PREFIX} scriptData 已更新`);
  }, [initialCategory, initialName, examplesMap]);

  // 处理选择示例脚本
  const handleSelectScript = (script: IScript) => {
    console.log(`${LOG_PREFIX} 选择示例脚本: ${script.name}`);

    // 创建脚本的副本
    const scriptCopy: IScript = {
      ...script,
      permissions: script.permissions ? [...script.permissions] : [],
    };
    console.log(`${LOG_PREFIX} 脚本副本创建完成, permissions 数量: ${scriptCopy.permissions?.length || 0}`);

    const proxiedScript = toProxy(scriptCopy);
    console.log(`${LOG_PREFIX} 脚本已使用 toProxy 包装`);

    setScriptData(proxiedScript);
    console.log(`${LOG_PREFIX} scriptData 已更新`);
  };

  // 处理运行脚本
  const handleRunScript = () => {
    console.log(`${LOG_PREFIX} 准备运行脚本`);

    if (!scriptData) {
      console.error(`${LOG_PREFIX} scriptData 为空, 无法运行`);
      return;
    }

    if (!scriptData.script) {
      console.error(`${LOG_PREFIX} 脚本内容为空, 无法运行`);
      return;
    }

    console.log(`${LOG_PREFIX} 脚本内容长度: ${scriptData.script.length}`);
    console.log(`${LOG_PREFIX} 脚本权限数量: ${scriptData.permissions?.length || 0}`);

    console.log(`${LOG_PREFIX} 使用 autoWebViewJs.callScript 运行`);
    autoWebViewJs.callScript(scriptData.script);

    console.log(`${LOG_PREFIX} 脚本运行完成`);
  };

  console.log(`${LOG_PREFIX} 组件渲染`);

  // 如果 context 正在加载
  if (isLoadingContext) {
    console.log(`${LOG_PREFIX} 渲染加载状态`);
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 200 }}>
        <CircularProgress />
      </Box>
    );
  }

  // 如果 context 加载失败
  if (contextError) {
    console.log(`${LOG_PREFIX} 渲染错误状态`);
    return (
      <Box sx={{ p: 2 }}>
        <Alert severity="error">
          {t('ScriptEditorContentV2.contextError')}: {contextError.message}
        </Alert>
      </Box>
    );
  }

  // 如果 context 数据不存在
  if (!contextData) {
    console.log(`${LOG_PREFIX} context 数据为空`);
    return null;
  }

  console.log(`${LOG_PREFIX} 渲染完整 UI`);

  return (
    <ScriptEditorContextProvider value={contextData}>
      <Box>
        <Typography variant="h5">
          {t(ns ? 'ScriptEditorContentV2.title.edit' : 'ScriptEditorContentV2.title.create')}
        </Typography>
        <Stack direction="column" spacing={2} sx={{ mt: 2 }}>
          {/* 加载状态 */}
          {isLoadingMap && (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <CircularProgress size={24} />
              <Typography variant="body2">{t('ScriptEditorContentV2.loading')}</Typography>
            </Box>
          )}

          {/* 错误显示 */}
          {mapError && (
            <Alert severity="error">
              {t('ScriptEditorContentV2.mapError')}: {mapError.message}
            </Alert>
          )}

          {scriptError && (
            <Alert severity="error">
              {t('ScriptEditorContentV2.scriptError')}: {scriptError.message}
            </Alert>
          )}

          {/* 示例脚本选择按钮 */}
          {examplesMap && (
            <ScriptExampleSelectorButton
              examplesMap={examplesMap}
              onSelectScript={handleSelectScript}
            />
          )}


          {/* 权限编辑器 */}
          {scriptData && (
            <ScriptPermissionsEditor scriptData={scriptData} />
          )}

          {/* 控制栏 */}
          {scriptData && (
            <ScriptControlBar scriptData={scriptData} onRun={handleRunScript} />
          )}

          {/* 脚本编辑器 */}
          {scriptData && (
            <ScriptEditor key={scriptData.path || 'default'} scriptData={scriptData} />
          )}

          {/* 运行结果显示区域，这个可能没有用 */}
          {runScript && (
            <Box>
              <Typography variant="h6">{t('ScriptEditorContentV2.result')}</Typography>
              <Box
                sx={{
                  p: 2,
                  bgcolor: 'grey.100',
                  borderRadius: 1,
                  fontFamily: 'monospace',
                  whiteSpace: 'pre-wrap',
                }}
              >
                {runScript}
              </Box>
            </Box>
          )}
        </Stack>
      </Box>
    </ScriptEditorContextProvider>
  );
}
