import { useProxyWatch, useProxyWatchUpdates, useTranslation } from '@fanfanlo';
import { Box, TextareaAutosize, Typography } from '@mui/material';
import type { IScript } from '../scripts/IScript';

// 日志前缀
const LOG_PREFIX = '[ScriptEditor]';

interface ScriptEditorProps {
  scriptData: IScript;
}

/**
 * 脚本编辑器组件
 * 编辑 IScript 对象的 script 字段
 */
export function ScriptEditor({ scriptData }: ScriptEditorProps) {
  console.log(`${LOG_PREFIX} 组件初始化`);

  const { t } = useTranslation('homepage/components/script-editor/content/v2/content');

  // 监听 scriptData.script 的变化
  const [script] = useProxyWatch(scriptData, 'script', scriptData.script);
  console.log(`${LOG_PREFIX} script 长度: ${script.length}`);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newValue = e.target.value;
    console.log(`${LOG_PREFIX} 脚本内容变化, 新长度: ${newValue.length}`);
    scriptData.script = newValue;
    console.log(`${LOG_PREFIX} 脚本内容已更新`);
  };

  return (
    <Box>
      <Typography variant="body2" sx={{ mb: 1, fontWeight: 500 }}>
        {t('ScriptEditor.label')}
      </Typography>
      <TextareaAutosize
        value={script}
        onChange={handleChange}
        style={{
          width: '100%',
          minHeight: '300px',
          padding: '8px',
          fontFamily: 'monospace',
          fontSize: '14px',
          border: '1px solid #ccc',
          borderRadius: '4px'
        }}
      />
    </Box>
  );
}
